<template><main class="customer-display"><IdleAdvertisement v-if="previewId || state.mode === 'idle'" :language="language" :preview-id="previewId" /><CartDisplay v-else-if="state.mode === 'cart'" :state="state" :language="language" :is-fullscreen="isFullscreen" @request-fullscreen="enterFullscreen" /><PaymentSuccess v-else :state="state" :language="language" /></main></template>
<script setup lang="ts">import { onBeforeUnmount, onMounted, ref, watch } from "vue"; import { useCustomerDisplay } from "@/composables/useCustomerDisplay"; import IdleAdvertisement from "@/components/customer-display/IdleAdvertisement.vue"; import CartDisplay from "@/components/customer-display/CartDisplay.vue"; import PaymentSuccess from "@/components/customer-display/PaymentSuccess.vue"; const { state } = useCustomerDisplay(); const params = new URLSearchParams(window.location.search); const language = ref<"en" | "ms">(localStorage.getItem("xpos.customerDisplay.language") === "ms" ? "ms" : "en"), previewId = params.get("preview") || ""; let timer: ReturnType<typeof setTimeout> | undefined; const isFullscreen = ref(false); function syncConfig(event: StorageEvent) { if (event.key === "xpos.customerDisplay.language") language.value = event.newValue === "ms" ? "ms" : "en"; } window.addEventListener("storage", syncConfig); function syncFullscreen() { isFullscreen.value = Boolean(document.fullscreenElement); } async function enterFullscreen() { try { await document.documentElement.requestFullscreen(); } catch { } } onMounted(() => { document.addEventListener("fullscreenchange", syncFullscreen); if (params.get("fullscreen") === "1") void enterFullscreen(); }); watch(() => state.value.mode, (mode) => { if (timer) clearTimeout(timer); if (mode === "payment") timer = setTimeout(() => { state.value = { ...state.value, mode: "idle" }; }, Math.max(5, Math.min(60, Number(localStorage.getItem("xpos.customerDisplay.returnDelay") || 10))) * 1000); }, { immediate: true }); onBeforeUnmount(() => { window.removeEventListener("storage", syncConfig); document.removeEventListener("fullscreenchange", syncFullscreen); });</script>
<style scoped>.customer-display{position:relative;height:100vh;width:100vw;overflow:hidden;background:#160f1b}</style>
